import type { DomainRegistry } from './registry.js';

/** Never 'ctxo-domain-': that prefix belongs to the ctxo-domain-fold skill. */
export const LOADER_RULE_PREFIX = 'ctxo-context-';
export const LOADER_RULE_MARKER = '<!-- generated by ctxo domain rules; do not edit -->';

export type LoaderPlatform = 'claude-code' | 'cursor';

/** A generated file; the path is repo-relative with forward slashes. */
export interface LoaderRuleFile {
  readonly path: string;
  readonly content: string;
}

export interface LoaderRulesDiff {
  readonly missing: readonly string[];
  readonly outdated: readonly string[];
  readonly stale: readonly string[];
  readonly foreign: readonly string[];
  /** Prefixed files without the marker at a path a generated file belongs at. */
  readonly blocked: readonly string[];
}

const compare = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

export function loaderRulePath(contextId: string, platform: LoaderPlatform): string {
  return platform === 'claude-code'
    ? `.claude/rules/${LOADER_RULE_PREFIX}${contextId}.md`
    : `.cursor/rules/${LOADER_RULE_PREFIX}${contextId}.mdc`;
}

/** One generated file per context with a card and per platform, in path order (spec 10.6). */
export function renderLoaderRules(registry: DomainRegistry, platforms: readonly LoaderPlatform[]): LoaderRuleFile[] {
  const files: LoaderRuleFile[] = [];
  for (const context of registry.contexts) {
    if (context.card === undefined) continue;
    const body = [
      LOADER_RULE_MARKER,
      `# ${context.name} context`,
      `Before changing code under these paths, read \`${context.card}\` (rules, contracts, decisions).`,
      `If behaviour changes, update that card in the same PR. If it does not, add \`Domain-Unchanged: ${context.id} (reason)\` to a commit.`,
    ];
    for (const platform of platforms) {
      const head =
        platform === 'claude-code'
          ? ['---', 'paths:', ...context.paths.map((glob) => `  - ${JSON.stringify(glob)}`), '---']
          : [
              '---',
              `description: ${context.name} context: read ${context.card} before changing this code`,
              `globs: ${context.paths.join(',')}`,
              'alwaysApply: false',
              '---',
            ];
      files.push({ path: loaderRulePath(context.id, platform), content: `${[...head, ...body].join('\n')}\n` });
    }
  }
  return files.sort((a, b) => compare(a.path, b.path));
}

function normalise(text: string): string {
  const noBom = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  return noBom.replace(/\r\n?/g, '\n');
}

/** Generated means the marker is the first line after the front matter, not merely somewhere in the file. */
export function isGeneratedRule(text: string): boolean {
  const lines = normalise(text).split(/\n/);
  if (lines[0] !== '---') return false;
  const close = lines.indexOf('---', 1);
  return close > 0 && lines[close + 1] === LOADER_RULE_MARKER;
}

/**
 * Compares the expected files with the prefixed files found on disk. A file with the marker that is not expected
 * is stale; a prefixed file without the marker is foreign (reported, never changed), or blocked when an expected file belongs at its path. CRLF and a BOM are ignored.
 */
export function diffLoaderRules(expected: readonly LoaderRuleFile[], existing: ReadonlyMap<string, string>): LoaderRulesDiff {
  const missing: string[] = [];
  const outdated: string[] = [];
  const stale: string[] = [];
  const foreign: string[] = [];
  const blocked: string[] = [];
  const expectedPaths = new Set<string>();
  for (const file of expected) {
    expectedPaths.add(file.path);
    const current = existing.get(file.path);
    if (current === undefined) missing.push(file.path);
    else if (!isGeneratedRule(current)) blocked.push(file.path);
    else if (normalise(current) !== file.content) outdated.push(file.path);
  }
  for (const [path, text] of existing) {
    if (expectedPaths.has(path)) continue;
    if (isGeneratedRule(text)) stale.push(path);
    else foreign.push(path);
  }
  return {
    missing: missing.sort(compare),
    outdated: outdated.sort(compare),
    stale: stale.sort(compare),
    foreign: foreign.sort(compare),
    blocked: blocked.sort(compare),
  };
}
